values(21,'speaking','Full Speaking · Day 21','published',$json${"version":"speaking-day-21-v1","part1":{"topic":"TOPIC 22. MORNING ROUTINES","questions":[{"key":"p1_q1","text":"What is your morning routine?"},{"key":"p1_q2","text":"Do you spend your mornings doing the same things on both weekends and weekdays?"},{"key":"p1_q3","text":"Is breakfast important?"},{"key":"p1_q4","text":"Do you like to get up early?"}]},"part2":{"key":"p2_main","topic":"TOPIC 21. TRAFFIC JAM","prompt":"Describe an occasion when you got stuck in a traffic jam.","bullets":["where you went","how often you do this","when you did this","why you dislike it"],"max_answer_seconds":120,"preparation_seconds":60},"part3":{"topic":"TOPIC 21. PUBLIC TRANSPORT, TRAFFIC JAMS","questions":[{"key":"p3_q1","text":"Would you rather be in a car or bus in a traffic jam?"},{"key":"p3_q2","text":"What are good ways to manage traffic?"},{"key":"p3_q3","text":"Do you think highways will help reduce traffic jams?"},{"key":"p3_q4","text":"In what ways can we fix traffic problems?"},{"key":"p3_q5","text":"Will there be fewer people using cars because of improved public transportation?"},{"key":"p3_q6","text":"Will there be fewer cars if public transport is free?"},{"key":"p3_q7","text":"What benefits does public transport bring to the world?"},{"key":"p3_q8","text":"What needs to be improved in public transport?"}]}}$json$::jsonb,now(),now())
